-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/marts/fact_diagnosis.sql. Do not edit.
-- Fact diagnosis. Grain: one row per encounter diagnosis, a Condition that points at a known encounter. Diagnoses
-- without an ICD 10 code point at the Unknown member of dim_diagnosis and keep the code system and code they came in.
CREATE OR REPLACE TABLE fact_diagnosis AS
SELECT
    MD5((SELECT pseudonym_salt FROM governance_settings) || '|' || COALESCE(CAST(c.condition_id AS VARCHAR), ''))                                                 AS diagnosis_fact_sk,
    MD5((SELECT pseudonym_salt FROM governance_settings) || '|' || COALESCE(CAST(c.encounter_id AS VARCHAR), ''))                                                 AS encounter_sk,
    k.patient_sk,
    CASE WHEN c.icd10_code IS NULL THEN 'unknown'
         ELSE MD5(COALESCE(CAST(c.icd10_code AS VARCHAR), '')) END                                  AS diagnosis_sk,
    CAST(EXTRACT(YEAR FROM CAST(c.recorded_at AS DATE)) * 10000 + EXTRACT(MONTH FROM CAST(c.recorded_at AS DATE)) * 100 + EXTRACT(DAY FROM CAST(c.recorded_at AS DATE)) AS INTEGER)                                        AS recorded_date_key,
    k.source,
    c.code_system,
    c.code                                                                               AS source_code,
    c.icd10_code,
    c.icd10_origin,
    c.needs_review
FROM silver_condition c
JOIN silver_encounter e       ON e.encounter_id = c.encounter_id
LEFT JOIN int_patient_key k   ON k.patient_id = c.patient_id;
